raw.css:
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  --color-primary-dark: #2d1b3d;
  --color-primary: #5a3a6f;
  --color-accent: #d4a574;
  --color-accent-on-dark: #f5e6d3;
  --color-text: #1a1a1a;
  --color-text-light: #f8f8f8;
  --color-bg: #fafafa;
  --color-border: #e0d5c7;
  --font-serif: Georgia, "Times New Roman", serif;
  --font-sans: Verdana, Arial, sans-serif;
  --spacing-xs: 0.5rem;
  --spacing-sm: 1rem;
  --spacing-md: 1.5rem;
  --spacing-lg: 2rem;
  --spacing-xl: 3rem;
  --spacing-2xl: 4rem;
  --radius: 4px;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-serif);
  color: var(--color-text);
  background-color: var(--color-bg);
  line-height: 1.6;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--spacing-md);
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-serif);
  font-weight: 400;
  letter-spacing: 0.05em;
  margin-bottom: var(--spacing-md);
}

h1 {
  font-size: 2.5rem;
  line-height: 1.2;
}

h2 {
  font-size: 2rem;
  color: var(--color-primary-dark);
}

h3 {
  font-size: 1.5rem;
  color: var(--color-primary);
}

p {
  margin-bottom: var(--spacing-md);
}

/* Links */
a {
  color: var(--color-primary-dark);
  text-decoration: none;
  border-bottom: 1px solid transparent;
  transition: all 0.2s ease;
}

a:hover,
a:focus {
  color: var(--color-accent);
  border-bottom-color: var(--color-accent);
}

a:focus {
  outline: 2px solid var(--color-primary-dark);
  outline-offset: 2px;
}

/* Header */
.site-header {
  background-color: #fff;
  border-bottom: 1px solid var(--color-border);
  padding: var(--spacing-md) 0;
  position: sticky;
  top: 0;
  z-index: 100;
}

.site-header .container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: var(--spacing-lg);
}

.logo {
  font-family: "Palatino Linotype", "Book Antiqua", serif;
  font-variant: small-caps;
  font-weight: 400;
  font-size: 1.5rem;
  letter-spacing: 0.15em;
  color: var(--color-primary-dark);
  border-bottom: 1px solid var(--color-accent);
  padding-bottom: 0.3rem;
  white-space: nowrap;
}

.logo:hover,
.logo:focus {
  color: var(--color-accent);
}

.site-header nav {
  display: flex;
  gap: var(--spacing-lg);
}

.site-header nav a {
  font-size: 1rem;
  color: var(--color-text);
  border-bottom: 2px solid transparent;
  padding-bottom: 0.25rem;
}

.site-header nav a:hover,
.site-header nav a:focus {
  color: var(--color-primary-dark);
  border-bottom-color: var(--color-accent);
}

/* Footer */
.site-footer {
  background-color: var(--color-primary-dark);
  color: var(--color-accent-on-dark);
  padding: var(--spacing-2xl) 0;
  margin-top: var(--spacing-2xl);
}

.site-footer a {
  color: var(--color-accent-on-dark);
  border-bottom-color: var(--color-accent);
}

.site-footer a:hover,
.site-footer a:focus {
  color: var(--color-accent);
}

.site-footer p {
  margin-bottom: var(--spacing-sm);
  font-size: 0.95rem;
}

.site-footer strong {
  color: var(--color-accent-on-dark);
}

/* Buttons */
button,
.btn {
  background-color: var(--color-primary-dark);
  color: var(--color-text-light);
  border: none;
  padding: var(--spacing-sm) var(--spacing-lg);
  font-size: 1rem;
  font-family: var(--font-serif);
  border-radius: var(--radius);
  cursor: pointer;
  min-height: 44px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: background-color 0.2s ease;
}

button:hover,
.btn:hover {
  background-color: var(--color-primary);
}

button:focus,
.btn:focus {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

/* Forms */
form {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-md);
}

label {
  display: block;
  margin-bottom: var(--spacing-xs);
  font-weight: 500;
  color: var(--color-text);
}

input[type="text"],
input[type="email"],
input[type="tel"],
input[type="date"],
textarea,
select {
  font-family: var(--font-serif);
  font-size: 1rem;
  padding: 0.75rem;
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  background-color: #fff;
  color: var(--color-text);
  min-height: 44px;
  transition: border-color 0.2s ease;
}

input[type="text"]:focus,
input[type="email"]:focus,
input[type="tel"]:focus,
input[type="date"]:focus,
textarea:focus,
select:focus {
  outline: none;
  border-color: var(--color-primary-dark);
  box-shadow: 0 0 0 2px rgba(45, 27, 61, 0.1);
}

textarea {
  min-height: 120px;
  resize: vertical;
}

/* Grid */
.grid {
  display: grid;
  gap: var(--spacing-lg);
}

.grid-2 {
  grid-template-columns: repeat(2, 1fr);
}

.grid-3 {
  grid-template-columns: repeat(3, 1fr);
}

.grid-4 {
  grid-template-columns: repeat(4, 1fr);
}

/* Cards */
.card {
  background-color: #fff;
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  overflow: hidden;
  transition: box-shadow 0.3s ease;
}

.card:hover {
  box-shadow: 0 4px 12px rgba(45, 27, 61, 0.1);
}

.card img {
  width: 100%;
  height: 280px;
  object-fit: cover;
  display: block;
}

.card-content {
  padding: var(--spacing-md);
}

/* Sections */
section {
  padding: var(--spacing-2xl) 0;
}

section h2 {
  text-align: center;
  margin-bottom: var(--spacing-2xl);
}

/* Mobile: max-width 600px */
@media (max-width: 600px) {
  :root {
    --spacing-md: 1rem;
    --spacing-lg: 1.5rem;
    --spacing-xl: 2rem;
    --spacing-2xl: 2.5rem;
  }

  h1 {
    font-size: 1.75rem;
  }

  h2 {
    font-size: 1.5rem;
  }

  h3 {
    font-size: 1.25rem;
  }

  .site-header .container {
    flex-direction: column;
    gap: var(--spacing-md);
  }

  .logo {
    font-size: 1.25rem;
  }

  .site-header nav {
    width: 100%;
    justify-content: center;
    gap: var(--spacing-md);
  }

  .grid-2,
  .grid-3,
  .grid-4 {
    grid-template-columns: 1fr;
  }

  .card img {
    height: 200px;
  }

  button,
  .btn {
    width: 100%;
  }

  input[type="text"],
  input[type="email"],
  input[type="tel"],
  input[type="date"],
  textarea,
  select {
    width: 100%;
  }
}

/* Desktop: min-width 601px */
@media (min-width: 601px) {
  .grid-2 {
    grid-template-columns: repeat(2, 1fr);
  }

  .grid-3 {
    grid-template-columns: repeat(3, 1fr);
  }

  .grid-4 {
    grid-template-columns: repeat(4, 1fr);
  }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

pages.css:
.hero {
  background: linear-gradient(135deg, var(--color-primary-dark) 0%, var(--color-primary) 100%);
  color: var(--color-text-light);
  padding: var(--spacing-2xl) 0;
  text-align: center;
}

.hero h1 {
  color: var(--color-text-light);
  font-size: 2.8rem;
  margin-bottom: var(--spacing-md);
}

.hero-subtitle {
  font-size: 1.25rem;
  margin-bottom: var(--spacing-2xl);
  color: var(--color-accent-on-dark);
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.hero-image {
  width: 100%;
  max-width: 800px;
  height: auto;
  border-radius: var(--radius);
  display: block;
  margin: 0 auto;
}

.services {
  background-color: #fff;
}

.service-card {
  background-color: var(--color-bg);
  padding: var(--spacing-lg);
  border-radius: var(--radius);
  border: 1px solid var(--color-border);
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.service-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 6px 16px rgba(45, 27, 61, 0.15);
}

.service-card h3 {
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-md);
}

.gallery {
  background-color: var(--color-bg);
}

.gallery .card {
  background-color: #fff;
}

.testimonials {
  background-color: #fff;
}

.testimonial-card {
  background-color: var(--color-bg);
  padding: var(--spacing-lg);
  border-radius: var(--radius);
  border-left: 4px solid var(--color-accent);
}

.testimonial-text {
  font-style: italic;
  color: var(--color-text);
  margin-bottom: var(--spacing-md);
  line-height: 1.8;
}

.testimonial-author {
  color: var(--color-primary-dark);
  font-weight: 500;
  margin-bottom: 0;
}

.contact {
  background-color: var(--color-bg);
}

.contact-wrapper {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-2xl);
}

.contact-info h3 {
  margin-bottom: var(--spacing-lg);
}

.contact-info p {
  margin-bottom: var(--spacing-lg);
  line-height: 1.8;
}

.contact-details {
  list-style: none;
  padding: 0;
}

.contact-details li {
  padding: var(--spacing-sm) 0;
  border-bottom: 1px solid var(--color-border);
}

.contact-details li:last-child {
  border-bottom: none;
}

.contact-details strong {
  color: var(--color-primary-dark);
  display: block;
  margin-bottom: var(--spacing-xs);
}

.contact-details a {
  color: var(--color-primary-dark);
}

.contact-form {
  background-color: #fff;
  padding: var(--spacing-lg);
  border-radius: var(--radius);
  border: 1px solid var(--color-border);
}

.contact-form fieldset {
  border: none;
  padding: 0;
  margin: 0;
}

.contact-form legend.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

.form-group {
  margin-bottom: var(--spacing-md);
}

.form-group label {
  display: block;
  margin-bottom: var(--spacing-xs);
  color: var(--color-text);
  font-weight: 500;
}

.form-group input,
.form-group textarea,
.form-group select {
  width: 100%;
  font-family: var(--font-serif);
  font-size: 1rem;
  padding: 0.75rem;
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  background-color: #fff;
  color: var(--color-text);
  min-height: 44px;
  transition: border-color 0.2s ease;
}

.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
  outline: none;
  border-color: var(--color-primary-dark);
  box-shadow: 0 0 0 2px rgba(45, 27, 61, 0.1);
}

.form-group textarea {
  min-height: 120px;
  resize: vertical;
}

.btn-submit {
  background-color: var(--color-primary-dark);
  color: var(--color-text-light);
  border: none;
  padding: var(--spacing-sm) var(--spacing-lg);
  font-size: 1rem;
  font-family: var(--font-serif);
  border-radius: var(--radius);
  cursor: pointer;
  min-height: 44px;
  width: 100%;
  transition: background-color 0.2s ease;
  font-weight: 500;
  letter-spacing: 0.05em;
}

.btn-submit:hover {
  background-color: var(--color-primary);
}

.btn-submit:focus {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

/* Mobile */
@media (max-width: 600px) {
  .hero h1 {
    font-size: 2rem;
  }

  .hero-subtitle {
    font-size: 1rem;
    margin-bottom: var(--spacing-lg);
  }

  .grid-3 {
    grid-template-columns: 1fr;
  }

  .contact-wrapper {
    grid-template-columns: 1fr;
    gap: var(--spacing-lg);
  }

  .contact-info {
    order: 2;
  }

  .contact-form {
    order: 1;
  }
}

/* Desktop */
@media (min-width: 601px) {
  .grid-3 {
    grid-template-columns: repeat(3, 1fr);
  }

  .contact-wrapper {
    grid-template-columns: 1fr 1fr;
  }
}

